import{_ as t,o as a,c as s,a8 as o}from"./chunks/framework.BppdKxCY.js";const k=JSON.parse('{"title":"EP.23 MCP 协议","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.23-mcp-protocol.md","filePath":"comics/EP.23-mcp-protocol.md","lastUpdated":1793421673000}'),l={name:"comics/EP.23-mcp-protocol.md"};function e(n,i,r,h,d,c){return a(),s("div",null,[...i[0]||(i[0]=[o(`<h1 id="ep-23-mcp-协议" tabindex="-1">EP.23 MCP 协议 <a class="header-anchor" href="#ep-23-mcp-协议" aria-label="Permalink to &quot;EP.23 MCP 协议&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../21-frontend-ai-interview">21-frontend-ai-interview.md</a>（21.4 MCP：模型上下文协议）· 关联：<code>examples/14-03-tool-ui.tsx</code>（工具调用卡 UI）</p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君要接 GitHub、数据库、订单系统三套工具，每接一个 AI 应用就要重写一遍适配，N×M 的泥潭。</li><li><strong>第 2 格</strong>：码叔亮出 MCP——<strong>Model Context Protocol（模型上下文协议）</strong>，给 AI 接外部能力的&quot;USB-C&quot;；三角色 Host / Client / Server，消息走 JSON-RPC 2.0。</li><li><strong>第 3 格</strong>：像素酱实证握手时序：<code>initialize</code> 协商能力 → <code>notifications/initialized</code> → <code>tools/list</code>（每个工具带 JSON Schema）→ <code>tools/call</code>，远程传输走 Streamable HTTP。</li><li><strong>第 4 格</strong>：码叔结案——MCP ≠ Function Calling；错误有三层；可重试才重试，全抖动退避 + 熔断；危险调用必须用户授权。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-n×m-适配爆炸" tabindex="-1">第 1 格 · N×M 适配爆炸 <a class="header-anchor" href="#第-1-格-·-n×m-适配爆炸" aria-label="Permalink to &quot;第 1 格 · N×M 适配爆炸&quot;">​</a></h3><ul><li>没有统一协议时，N 个 AI 应用 × M 个工具 = N×M 套私有对接；</li><li>工具发现、鉴权、流式进度、错误码各搞各的；</li><li>MCP 把它变成 N+M：任何 Host 都能即插即用任何 Server。</li></ul><h3 id="第-2-格-·-三角色与-json-rpc" tabindex="-1">第 2 格 · 三角色与 JSON-RPC <a class="header-anchor" href="#第-2-格-·-三角色与-json-rpc" aria-label="Permalink to &quot;第 2 格 · 三角色与 JSON-RPC&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td>Host</td><td>用户的 AI 应用（Claude Desktop/IDE/客服工作台），管权限与 UI</td></tr><tr><td>Client</td><td>Host 内与每个 Server 维持的 1:1 协议连接</td></tr><tr><td>Server</td><td>暴露 tools / resources / prompts 的本地或远程服务</td></tr></tbody></table><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tools/call&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;query_order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;orderId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1024&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }</span></span></code></pre></div><ul><li>请求带 <code>id</code> 且必须有响应；通知（notification）无 <code>id</code>；</li><li>传输两种：<strong>stdio</strong>（本地子进程，每行一条）与 <strong>Streamable HTTP</strong>（远程单端点，可升级 SSE 流式，2025 规范取代旧的 HTTP+SSE 双端点）。</li></ul><h3 id="第-3-格-·-生命周期与工具契约" tabindex="-1">第 3 格 · 生命周期与工具契约 <a class="header-anchor" href="#第-3-格-·-生命周期与工具契约" aria-label="Permalink to &quot;第 3 格 · 生命周期与工具契约&quot;">​</a></h3><ul><li><code>initialize</code> 交换协议版本与 capabilities → 客户端发 initialized 通知 → 才能 list/call；</li><li>工具入参是 <strong>JSON Schema</strong>：调用前先本地校验（模型可能幻觉出非法参数），用户授权后再发 Server；</li><li>清单缓存 + <code>tools/list_changed</code> 通知增量更新；</li><li>流式工具调用通过 SSE 下发进度，前端渲染&quot;检索中…&quot;步骤卡。</li></ul><h3 id="第-4-格-·-与-function-calling-的边界-最高频考点" tabindex="-1">第 4 格 · 与 Function Calling 的边界（最高频考点） <a class="header-anchor" href="#第-4-格-·-与-function-calling-的边界-最高频考点" aria-label="Permalink to &quot;第 4 格 · 与 Function Calling 的边界（最高频考点）&quot;">​</a></h3><ul><li><strong>Function Calling 是&quot;模型的嘴&quot;</strong>：模型输出结构化调用意图，是一次推理能力；</li><li><strong>MCP 是&quot;应用的手&quot;</strong>：应用与工具服务器之间怎么连、怎么发现、怎么协商、怎么传结果；</li><li>一条链路：模型 function-call → Host 校验授权 → 经 MCP <code>tools/call</code> 执行 → 结果回灌模型续写；</li><li>三层失败：传输故障 / JSON-RPC 标准错误码（-32602 参数非法等）/ 协议成功但 <code>isError:true</code> 业务失败，再加用户拒绝授权——处理策略各不相同。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../21-frontend-ai-interview#_21-7-3-常见误区总清单">《21.7.3 常见误区总清单》</a></p></blockquote><ol><li>名字说错：MCP 是 Model <strong>Context</strong> Protocol，不是 Control；</li><li>把 MCP 与 Function Calling 混为一谈——前者是连接协议，后者是模型能力，互补；</li><li>对 -32602/-32601 这类确定性错误做重试：永远不会成功，应立即失败；</li><li>盲目信任社区 Server：要沙箱化、最小权限、审计其资源访问；</li><li>写操作不做二次确认：模型意图不等于用户授权。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>MCP 解决什么问题？三角色分别是什么？</strong>——统一 AI 应用接入外部工具/资源/提示词的协议，把 N×M 变 N+M；Host（AI 应用，管权限）、Client（与 Server 1:1 的连接）、Server（暴露 tools/resources/prompts）。</li><li><strong>MCP 握手流程？</strong>——initialize 协商协议版本与能力 → notifications/initialized → tools/list 发现工具 → tools/call 调用；stdio 与 Streamable HTTP 两种传输，后者支持流式进度。</li><li><strong>工具调用失败有哪几类？如何处理？</strong>——传输/5xx/-32603 可按全抖动指数退避重试并配熔断；-32602/-32601 参数或方法错误立即失败并回喂模型修正；<code>isError:true</code> 属业务失败按业务提示；权限拒绝走明确 UI 不静默重试。</li></ol>`,20)])])}const u=t(l,[["render",e]]);export{k as __pageData,u as default};
